-- ORDER-CHAIN-UNIVERSAL-1A (preflight). No USE statement: the operator selects the target database in the tool.
-- One standard text for every KeepStore database: it names no database, customer or domain. The only run-time input are the session
-- variables listed below and, in forward and rollback, the DEFINER slot (see DEFINER SLOT).
-- Run only by the Product Owner, one database at a time, after an explicit go for that database. Never use --force. Stop the script on the first error.
-- Text comparisons use a canonical form (CRLF as LF, trailing blanks and empty lines ignored; a lone CR is not): SQLyog removes the empty lines of a script, so the stored text differs from the file while the code is the same. Needs MySQL 8.0.17 or newer (REGEXP_REPLACE returns UTF-8 from 8.0.17), not MariaDB: checked below. The canonical form would equate two different multi-line string literals; no body has one (checked by Tools/Test-OrderChainUniversal.ps1): re-check that when a body changes.
-- Read-only. Starting level: Carrello_Documento is the atomic-reservation body (the version installed since 2026-09-12, CRLF or LF; empty lines and trailing blanks do not matter), absent Carrello_Totali.
-- Target level: Carrello_Documento and Carrello_Totali after ORDER-VAT-ID-SEMANTICS-P1, ORDER-DOCUMENT-NUMBER-OUT-P0B, ORDER-ROUNDING-HALF-UP and ORDER-TOTALS-DB-SOURCE.
-- Output: one grid (key, value). Row 03 is the definer literal for the DEFINER slot. Row 99 must be OK before the forward.
SET SESSION group_concat_max_len=4096;
SET @ks_ck_doc_text=IF((SELECT COUNT(*) FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA=DATABASE() AND ROUTINE_NAME='Carrello_Documento' AND ROUTINE_TYPE='PROCEDURE' AND SHA2(REGEXP_REPLACE(REGEXP_REPLACE(CONVERT(REPLACE(ROUTINE_DEFINITION,CONCAT(CHAR(13),CHAR(10)),CHAR(10)) USING utf8mb4),CONCAT('[ ',CONVERT(CHAR(9) USING utf8mb4),']*',CONVERT(CHAR(10) USING utf8mb4)),CONVERT(CHAR(10) USING utf8mb4)),CONCAT(CONVERT(CHAR(10) USING utf8mb4),'+'),CONVERT(CHAR(10) USING utf8mb4)),256) IN ('9030ec6c06d33db5d0a5ce455ddb953d06ccd77e37ab43775ec4ce997494618a','351380c3c211ed7701747a95bbed0148cf03f995747ce4c18d3120a6c934a055','fdc6cb6f0200113382c4c40a882320eac55bff2c3699e0af5c8ca996dc4182d4'))=1,1,0);
SET @ks_ck_doc_attr=IF((SELECT COUNT(*) FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA=DATABASE() AND ROUTINE_NAME='Carrello_Documento' AND ROUTINE_TYPE='PROCEDURE' AND SECURITY_TYPE='DEFINER' AND IS_DETERMINISTIC='NO' AND SQL_DATA_ACCESS='CONTAINS SQL' AND ROUTINE_COMMENT='' AND SQL_MODE='NO_AUTO_VALUE_ON_ZERO')=1,1,0);
SET @ks_ck_doc_meta=IF((SELECT COUNT(*) FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA=DATABASE() AND ROUTINE_NAME='Carrello_Documento' AND ROUTINE_TYPE='PROCEDURE' AND ((CHARACTER_SET_CLIENT='utf8mb4' AND COLLATION_CONNECTION='utf8mb4_0900_ai_ci') OR (CHARACTER_SET_CLIENT='utf8mb3' AND COLLATION_CONNECTION='utf8mb3_general_ci')))=1,1,0);
SET @ks_ck_doc_dbcoll=IF((SELECT COUNT(*) FROM information_schema.ROUTINES r JOIN information_schema.SCHEMATA s ON CONVERT(s.SCHEMA_NAME USING utf8mb4) COLLATE utf8mb4_bin=CONVERT(r.ROUTINE_SCHEMA USING utf8mb4) COLLATE utf8mb4_bin WHERE r.ROUTINE_SCHEMA=DATABASE() AND r.ROUTINE_NAME='Carrello_Documento' AND r.ROUTINE_TYPE='PROCEDURE' AND CONVERT(r.DATABASE_COLLATION USING utf8mb4) COLLATE utf8mb4_bin=CONVERT(s.DEFAULT_COLLATION_NAME USING utf8mb4) COLLATE utf8mb4_bin)=1,1,0);
SET @ks_ck_doc_sig=IF((SELECT COUNT(*) FROM information_schema.PARAMETERS WHERE SPECIFIC_SCHEMA=DATABASE() AND SPECIFIC_NAME='Carrello_Documento' AND PARAMETER_MODE IN('IN','OUT'))=19 AND (SELECT SHA2(GROUP_CONCAT(CONCAT_WS(':',ORDINAL_POSITION,PARAMETER_MODE,PARAMETER_NAME,DATA_TYPE,COALESCE(CHARACTER_MAXIMUM_LENGTH,''),COALESCE(NUMERIC_PRECISION,''),COALESCE(NUMERIC_SCALE,'')) ORDER BY ORDINAL_POSITION SEPARATOR '|'),256) FROM information_schema.PARAMETERS WHERE SPECIFIC_SCHEMA=DATABASE() AND SPECIFIC_NAME='Carrello_Documento')='953b867c730f382dfc87975f3bd74a417e3946b3c977ce2075e8043134c6aaaa' AND (SELECT COUNT(*) FROM information_schema.PARAMETERS q JOIN information_schema.SCHEMATA s ON CONVERT(s.SCHEMA_NAME USING utf8mb4) COLLATE utf8mb4_bin=CONVERT(q.SPECIFIC_SCHEMA USING utf8mb4) COLLATE utf8mb4_bin WHERE q.SPECIFIC_SCHEMA=DATABASE() AND q.SPECIFIC_NAME='Carrello_Documento' AND q.CHARACTER_SET_NAME IS NOT NULL AND NOT (CONVERT(q.CHARACTER_SET_NAME USING utf8mb4) COLLATE utf8mb4_bin=CONVERT(s.DEFAULT_CHARACTER_SET_NAME USING utf8mb4) COLLATE utf8mb4_bin AND CONVERT(q.COLLATION_NAME USING utf8mb4) COLLATE utf8mb4_bin=CONVERT(s.DEFAULT_COLLATION_NAME USING utf8mb4) COLLATE utf8mb4_bin))=0,1,0);
SET @ks_ck_doc_all=IF(@ks_ck_doc_text=1 AND @ks_ck_doc_attr=1 AND @ks_ck_doc_meta=1 AND @ks_ck_doc_dbcoll=1 AND @ks_ck_doc_sig=1,1,0);
SET @ks_ck_totali_absent=IF((SELECT COUNT(*) FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA=DATABASE() AND ROUTINE_NAME='Carrello_Totali' AND ROUTINE_TYPE='PROCEDURE')=0,1,0);
SET @ks_ck_probe_absent=IF((SELECT COUNT(*) FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA=DATABASE() AND ROUTINE_NAME='ks_chain_definer_probe' AND ROUTINE_TYPE='PROCEDURE')=0,1,0);
SET @ks_ck_t_documenti=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='documenti' AND ((COLUMN_NAME='id' AND COLUMN_KEY='PRI' AND EXTRA LIKE '%auto_increment%') OR COLUMN_NAME='NDocumento'))=2,1,0);
SET @ks_ck_t_pie=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='documentipie' AND COLUMN_NAME IN('TotaleDocumento','TotMerce') AND COLUMN_TYPE='double(15,5)')=2,1,0);
SET @ks_ck_t_vcarrello=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='vcarrello' AND COLUMN_NAME IN('LoginId','Importo','IdIvaRC','ValoreIvaRC','idEsenzioneIva','ValoreEsenzioneIva','Valoreiva'))=7,1,0);
SET @ks_ck_t_engine=IF((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN('documenti','documentipie') AND ENGINE='InnoDB')=2,1,0);
SET @ks_chain_ver=SUBSTRING_INDEX(VERSION(),'-',1);
SET @ks_ck_version=IF(VERSION() NOT LIKE '%MariaDB%' AND CAST(SUBSTRING_INDEX(@ks_chain_ver,'.',1) AS UNSIGNED)*10000+CAST(SUBSTRING_INDEX(SUBSTRING_INDEX(@ks_chain_ver,'.',2),'.',-1) AS UNSIGNED)*100+CAST(SUBSTRING_INDEX(@ks_chain_ver,'.',-1) AS UNSIGNED)>=80017,1,0);
SET @ks_ck_overall=IF(@ks_ck_doc_text=1 AND @ks_ck_doc_attr=1 AND @ks_ck_doc_meta=1 AND @ks_ck_doc_dbcoll=1 AND @ks_ck_doc_sig=1 AND @ks_ck_totali_absent=1 AND @ks_ck_probe_absent=1 AND @ks_ck_t_documenti=1 AND @ks_ck_t_pie=1 AND @ks_ck_t_vcarrello=1 AND @ks_ck_t_engine=1 AND @ks_ck_version=1,1,0);
SELECT CONVERT('01 identity (database | version | server uuid)' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS k, CONVERT(CONCAT_WS(' | ', DATABASE(), VERSION(), @@server_uuid) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS v
UNION ALL SELECT CONVERT('02 installed Carrello_Documento (definer | security | canonical sha256 | raw length)' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT((SELECT CONCAT_WS(' | ', DEFINER, SECURITY_TYPE, SHA2(REGEXP_REPLACE(REGEXP_REPLACE(CONVERT(REPLACE(ROUTINE_DEFINITION,CONCAT(CHAR(13),CHAR(10)),CHAR(10)) USING utf8mb4),CONCAT('[ ',CONVERT(CHAR(9) USING utf8mb4),']*',CONVERT(CHAR(10) USING utf8mb4)),CONVERT(CHAR(10) USING utf8mb4)),CONCAT(CONVERT(CHAR(10) USING utf8mb4),'+'),CONVERT(CHAR(10) USING utf8mb4)),256), CHAR_LENGTH(ROUTINE_DEFINITION)) FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA=DATABASE() AND ROUTINE_NAME='Carrello_Documento' AND ROUTINE_TYPE='PROCEDURE' LIMIT 1) USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('03 DEFINER LITERAL for the slot (copy this)' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT((SELECT CONCAT('`',REPLACE(SUBSTRING(DEFINER,1,CHAR_LENGTH(DEFINER)-CHAR_LENGTH(SUBSTRING_INDEX(DEFINER,'@',-1))-1),'`','``'),'`@`',REPLACE(SUBSTRING_INDEX(DEFINER,'@',-1),'`','``'),'`') FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA=DATABASE() AND ROUTINE_NAME='Carrello_Documento' AND ROUTINE_TYPE='PROCEDURE' LIMIT 1) USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('04 installed metadata (client | connection | database collation | sql_mode)' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT((SELECT CONCAT_WS(' | ', CHARACTER_SET_CLIENT, COLLATION_CONNECTION, DATABASE_COLLATION, SQL_MODE) FROM information_schema.ROUTINES WHERE ROUTINE_SCHEMA=DATABASE() AND ROUTINE_NAME='Carrello_Documento' AND ROUTINE_TYPE='PROCEDURE' LIMIT 1) USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('10 Carrello_Documento text is a known starting text' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(IF(@ks_ck_doc_text=1,'OK','STOP') USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('11 security DEFINER, characteristics, sql_mode NO_AUTO_VALUE_ON_ZERO' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(IF(@ks_ck_doc_attr=1,'OK','STOP') USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('12 client charset and connection collation are a tested pair' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(IF(@ks_ck_doc_meta=1,'OK','STOP') USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('13 routine database collation equals the database default' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(IF(@ks_ck_doc_dbcoll=1,'OK','STOP') USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('14 19 parameters, expected signature, string parameters in the database default charset and collation' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(IF(@ks_ck_doc_sig=1,'OK','STOP') USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('15 Carrello_Totali absent' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(IF(@ks_ck_totali_absent=1,'OK','STOP') USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('16 definer probe procedure absent' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(IF(@ks_ck_probe_absent=1,'OK','STOP') USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('17 documenti columns' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(IF(@ks_ck_t_documenti=1,'OK','STOP') USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('18 documentipie columns' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(IF(@ks_ck_t_pie=1,'OK','STOP') USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('19 vcarrello columns' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(IF(@ks_ck_t_vcarrello=1,'OK','STOP') USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('20 InnoDB tables' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(IF(@ks_ck_t_engine=1,'OK','STOP') USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('21 MySQL 8.0.17 or newer, not MariaDB (the canonical form needs REGEXP_REPLACE with UTF-8 results)' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(IF(@ks_ck_version=1,'OK','STOP') USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('90 routine-level grants (this script cannot see them)' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT('record them (diagnosis row 08) before the forward and compare after it; none expected. Do not reopen checkout without that comparison' USING utf8mb4) COLLATE utf8mb4_unicode_ci
UNION ALL SELECT CONVERT('99 OVERALL: the forward may start' USING utf8mb4) COLLATE utf8mb4_unicode_ci, CONVERT(IF(@ks_ck_overall=1,'OK','STOP') USING utf8mb4) COLLATE utf8mb4_unicode_ci
ORDER BY k;
